+        detail::ffi::DLTensor tensors[MAX_ARGS];
+        std::copy(proto_.begin(), proto_.end(), args);
+        int t = 0;
+        for (auto const &b : binds_) {
+            uintptr_t const base = b.operand >= 0           ? reinterpret_cast<uintptr_t>(data[b.operand])
