+            b.arg = static_cast<int>(i);
+            if (a.contains("stream")) {
+                b.as = As::STREAM;
+                binds_.push_back(b);
+                continue;
+            }
+            if (a.contains("operand")) {
+                auto const name = a.at("operand").get<std::string>();
