+                RETURN_CUDNN_FRONTEND_ERROR_IF(!detail::dl_dtype(v.dtype, b.dtype),
+                                               error_code_t::GRAPH_NOT_SUPPORTED,
+                                               "GroupedGemm: operand " + a.at("operand").get<std::string>() +
